using RealmForge.Domain.Entities;
using RealmForge.Shared.Enums;

namespace RealmForge.Infrastructure.Persistence.Seeding.ClassesData;

///	<summary>
///	Way of the Four Elements (monk, 2014 ruleset). Not in the SRD: names and mechanics as in the rules, with descriptions written for RealmForge in English and Italian.
///	</summary>
public static class WayOfTheFourElements2014Seeder
{
	public static readonly Guid SubclassId = DeterministicGuid.ForSrd(RulesetVersion.Dnd5e_2014, "subclass", "way-of-the-four-elements");

	public static Subclass Build()
	{
		return new Subclass
		{
			Id = SubclassId,
			CharacterClassId = Monk2014Seeder.ClassId,
			Ruleset = RulesetVersion.Dnd5e_2014,
			IsOfficialSRD = true,
			Source = ContentSource.RealmForge,
			CasterProgression = CasterProgression.None,
			SpellcastingAbility = null,
			Translations = new List<SubclassTranslation>
			{
				new SubclassTranslation { Id = DeterministicGuid.ForSrd(RulesetVersion.Dnd5e_2014, "subclass", "way-of-the-four-elements", "en"), Language = LanguageCode.En, Name = "Way of the Four Elements", Description = "Monks of this tradition learn to bend air, earth, fire, and water to their will, using the elements as an extension of their own bodies. Some devote themselves to a single element, others weave them all together. Many decorate their bodies with tattoos of their ki powers: coiling dragons above all, but also phoenixes, fish, plants, mountains and breaking waves." },
				new SubclassTranslation { Id = DeterministicGuid.ForSrd(RulesetVersion.Dnd5e_2014, "subclass", "way-of-the-four-elements", "it"), Language = LanguageCode.It, Name = "Via dei Quattro Elementi", Description = "I monaci di questa tradizione imparano a piegare aria, terra, fuoco e acqua alla loro volontà, usando gli elementi come un'estensione del proprio corpo. Alcuni si dedicano a un solo elemento, altri li intrecciano tutti. Molti decorano il corpo con tatuaggi che rappresentano i loro poteri ki: soprattutto draghi attorcigliati, ma anche fenici, pesci, piante, montagne e onde che si infrangono." }
			},
			Features = new List<ClassFeature>
			{
				new ClassFeature
				{
					Id = DeterministicGuid.ForSrd(RulesetVersion.Dnd5e_2014, "class-feature", "way-of-the-four-elements/disciple-of-the-elements"),
					Ruleset = RulesetVersion.Dnd5e_2014,
					Level = 3,
					SortOrder = 0,
					Translations = new List<ClassFeatureTranslation>
					{
						new ClassFeatureTranslation { Id = DeterministicGuid.ForSrd(RulesetVersion.Dnd5e_2014, "class-feature", "way-of-the-four-elements/disciple-of-the-elements", "en"), Language = LanguageCode.En, Name = "Disciple of the Elements", Description = "At 3rd level, you learn elemental disciplines, magical techniques that cost ki points each time you use them. You know Elemental Attunement plus one other discipline of your choice from the list below, and you learn one more at 6th, 11th, and 17th level. Whenever you learn a new discipline, you can also swap one discipline you know for another. If a discipline lists a required level, you must be at least that monk level to learn it.\n\n**Casting elemental spells.** Some disciplines let you cast spells: use the spell's casting time and rules, but you don't need its material components. From 5th monk level, you can spend extra ki points to cast such a spell at a higher level, if the spell improves when cast with a higher slot (as *burning hands* does): each extra ki point raises the spell's level by 1. For example, a 5th-level monk using Sweeping Cinder Strike can spend 3 ki points to cast *burning hands* as a 2nd-level spell (2 for the discipline, plus 1). The total ki you can spend on one such spell, including the base cost, depends on your monk level:\n\n| Monk Level | Maximum Ki Points for a Spell |\n|---|---|\n| 5th–8th | 3 |\n| 9th–12th | 4 |\n| 13th–16th | 5 |\n| 17th–20th | 6 |\n\n**Elemental disciplines**\n\n***Breath of Winter (17th level).*** Spend 6 ki points to cast *cone of cold*.\n\n***Clench of the North Wind (6th level).*** Spend 3 ki points to cast *hold person*.\n\n***Elemental Attunement.*** As an action, you briefly command the elements around you to produce one of these effects:\n- a harmless, instantaneous sensory effect tied to air, earth, fire or water, such as a shower of sparks, a puff of wind, a light mist or a low rumble of stone;\n- instantly lighting or putting out a candle, a torch or a small campfire;\n- chilling or warming up to 1 pound of nonliving material for up to 1 hour;\n- making earth, fire, water or mist that fits in a 1-foot cube take a crude shape of your choice for 1 minute.\n\n***Eternal Mountain Defense (17th level).*** Spend 5 ki points to cast *stoneskin* on yourself.\n\n***Fangs of the Fire Snake.*** When you take the Attack action on your turn, you can spend 1 ki point to make flames lash out from your fists and feet: your unarmed strikes gain 10 feet of reach for that action and the rest of the turn, and they deal fire damage instead of bludgeoning damage. When one of those attacks hits, you can spend 1 more ki point to add 1d10 fire damage.\n\n***Fist of Four Thunders.*** Spend 2 ki points to cast *thunderwave*.\n\n***Fist of Unbroken Air.*** As an action, you spend 2 ki points to hurl a fist of compressed air at a creature within 30 feet of you, which makes a Strength saving throw. On a failure, it takes 3d10 bludgeoning damage, plus 1d10 for each extra ki point you spend, and you can push it up to 20 feet away from you and knock it prone. On a success, it takes half the damage and is neither pushed nor knocked prone.\n\n***Flames of the Phoenix (11th level).*** Spend 4 ki points to cast *fireball*.\n\n***Gong of the Summit (6th level).*** Spend 3 ki points to cast *shatter*.\n\n***Mist Stance (11th level).*** Spend 4 ki points to cast *gaseous form* on yourself.\n\n***Ride the Wind (11th level).*** Spend 4 ki points to cast *fly* on yourself.\n\n***River of Hungry Flame (17th level).*** Spend 5 ki points to cast *wall of fire*.\n\n***Rush of the Gale Spirits.*** Spend 2 ki points to cast *gust of wind*.\n\n***Shape the Flowing River.*** As an action, you spend 1 ki point and choose an area of ice or water no larger than 30 feet on a side within 120 feet of you. You can turn water into ice and ice into water within it, and reshape the ice however you like: raise or lower it, dig or fill a trench, raise or flatten a wall, or form a pillar. No change can exceed half the area's largest dimension (in a 30-foot square, for instance, a pillar can be at most 15 feet tall), and you can't shape the ice to trap or harm a creature in the area.\n\n***Sweeping Cinder Strike.*** Spend 2 ki points to cast *burning hands*.\n\n***Water Whip.*** As a bonus action, you spend 2 ki points to lash a creature you can see within 30 feet of you with a whip of water; it makes a Dexterity saving throw. On a failure, it takes 3d10 bludgeoning damage, plus 1d10 for each extra ki point you spend, and you can either knock it prone or pull it up to 25 feet closer to you. On a success, it takes half the damage and is neither pulled nor knocked prone.\n\n***Wave of Rolling Earth (17th level).*** Spend 6 ki points to cast *wall of stone*." },
						new ClassFeatureTranslation { Id = DeterministicGuid.ForSrd(RulesetVersion.Dnd5e_2014, "class-feature", "way-of-the-four-elements/disciple-of-the-elements", "it"), Language = LanguageCode.It, Name = "Discepolo degli Elementi", Description = "Al 3° livello il monaco apprende le discipline elementali, tecniche magiche che costano punti ki ogni volta che le usa. Conosce Sintonia Elementale più un'altra disciplina a sua scelta dalla lista seguente, e ne apprende un'altra al 6°, all'11° e al 17° livello. Ogni volta che apprende una nuova disciplina, può anche sostituire una disciplina che conosce con un'altra. Se una disciplina indica un livello richiesto, il monaco deve essere almeno di quel livello per apprenderla.\n\n**Lanciare incantesimi elementali.** Alcune discipline permettono di lanciare incantesimi: il monaco usa il tempo di lancio e le regole dell'incantesimo, ma non ha bisogno delle sue componenti materiali. Dal 5° livello da monaco, può spendere punti ki aggiuntivi per lanciare un incantesimo del genere a un livello più alto, se l'incantesimo migliora quando è lanciato con uno slot superiore (come *mani brucianti*): ogni punto ki aggiuntivo aumenta di 1 il livello dell'incantesimo. Per esempio, un monaco di 5° livello che usa Colpo della Cenere Turbinante può spendere 3 punti ki per lanciare *mani brucianti* come incantesimo di 2° livello (2 per la disciplina, più 1). Il totale di ki che il monaco può spendere per un singolo incantesimo di questo tipo, incluso il costo di base, dipende dal suo livello da monaco:\n\n| Livello da monaco | Massimo di punti ki per un incantesimo |\n|---|---|\n| 5°–8° | 3 |\n| 9°–12° | 4 |\n| 13°–16° | 5 |\n| 17°–20° | 6 |\n\n**Discipline elementali**\n\n***Soffio dell'Inverno (17° livello).*** Spendere 6 punti ki per lanciare *cono di freddo*.\n\n***Morsa del Vento del Nord (6° livello).*** Spendere 3 punti ki per lanciare *blocca persone*.\n\n***Sintonia Elementale.*** Come azione, il monaco comanda brevemente gli elementi che lo circondano per produrre uno di questi effetti:\n- un effetto sensoriale innocuo e istantaneo legato all'aria, alla terra, al fuoco o all'acqua, come una pioggia di scintille, uno sbuffo di vento, una leggera foschia o un sommesso brontolio della pietra;\n- accendere o spegnere all'istante una candela, una torcia o un piccolo fuoco da campo;\n- raffreddare o scaldare fino a 0,5 kg di materiale non vivente per un massimo di 1 ora;\n- far assumere a terra, fuoco, acqua o nebbia che stanno in un cubo di 30 centimetri di spigolo una forma grossolana a scelta del monaco per 1 minuto.\n\n***Difesa della Montagna Eterna (17° livello).*** Spendere 5 punti ki per lanciare *pelle di pietra* su se stesso.\n\n***Zanne del Serpente di Fuoco.*** Quando effettua l'azione di Attacco nel suo turno, il monaco può spendere 1 punto ki per far scaturire fiamme dai pugni e dai piedi: i suoi colpi senz'armi ottengono 3 metri di portata per quell'azione e per il resto del turno, e infliggono danni da fuoco anziché contundenti. Quando uno di quegli attacchi va a segno, può spendere 1 altro punto ki per aggiungere 1d10 danni da fuoco.\n\n***Pugno dei Quattro Tuoni.*** Spendere 2 punti ki per lanciare *onda tonante*.\n\n***Pugno dell'Aria Inviolabile.*** Come azione, il monaco spende 2 punti ki per scagliare un pugno di aria compressa contro una creatura entro 9 metri da lui, che effettua un tiro salvezza su Forza. Se lo fallisce, subisce 3d10 danni contundenti, più 1d10 per ogni punto ki aggiuntivo speso, e il monaco può spingerla fino a 6 metri lontano da sé e buttarla a terra prona. Se lo supera, subisce la metà dei danni e non viene né spinta né buttata a terra.\n\n***Fiamme della Fenice (11° livello).*** Spendere 4 punti ki per lanciare *palla di fuoco*.\n\n***Gong della Sommità (6° livello).*** Spendere 3 punti ki per lanciare *frantumare*.\n\n***Postura della Nebbia (11° livello).*** Spendere 4 punti ki per lanciare *forma gassosa* su se stesso.\n\n***Cavalcare il Vento (11° livello).*** Spendere 4 punti ki per lanciare *volare* su se stesso.\n\n***Fiume della Fiamma Famelica (17° livello).*** Spendere 5 punti ki per lanciare *muro di fuoco*.\n\n***Spiriti della Burrasca Impetuosa.*** Spendere 2 punti ki per lanciare *folata di vento*.\n\n***Forma del Fiume Fluente.*** Come azione, il monaco spende 1 punto ki e sceglie un'area di ghiaccio o di acqua di non più di 9 metri di lato entro 36 metri da lui. Al suo interno può trasformare l'acqua in ghiaccio e il ghiaccio in acqua, e modellare il ghiaccio a piacimento: alzarlo o abbassarlo, scavare o riempire una trincea, innalzare o spianare un muro, oppure formare un pilastro. Nessuna modifica può superare la metà della dimensione maggiore dell'area (in un quadrato di 9 metri di lato, per esempio, un pilastro può essere alto al massimo 4,5 metri), e il monaco non può modellare il ghiaccio per intrappolare o ferire una creatura nell'area.\n\n***Colpo della Cenere Turbinante.*** Spendere 2 punti ki per lanciare *mani brucianti*.\n\n***Frusta d'Acqua.*** Come azione bonus, il monaco spende 2 punti ki per sferzare con una frusta d'acqua una creatura entro 9 metri da lui che è in grado di vedere; la creatura effettua un tiro salvezza su Destrezza. Se lo fallisce, subisce 3d10 danni contundenti, più 1d10 per ogni punto ki aggiuntivo speso, e il monaco può buttarla a terra prona oppure tirarla fino a 7,5 metri più vicino a sé. Se lo supera, subisce la metà dei danni e non viene né tirata né buttata a terra.\n\n***Onda della Terra Tumultuosa (17° livello).*** Spendere 6 punti ki per lanciare *muro di pietra*." }
					}
				}
			}
		};
	}
}
